#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> destino: $DEST"
echo "" | base64 -d > "$DEST/scrub_oracle.py"
echo "" | base64 -d > "$DEST/gen_layer2_vectors.py"
echo "" | base64 -d > "$DEST/scrub_bram.vhd"
echo "" | base64 -d > "$DEST/scrub_fsm.vhd"
echo "" | base64 -d > "$DEST/tb_layer2.vhd"
echo ">> generando vectores Layer 2"
( cd "$DEST" && python3 gen_layer2_vectors.py )
echo ">> analizando + corriendo Layer 2 en GHDL"
( cd "$DEST" && rm -rf work-obj08.cf && \
  ghdl -a --std=08 ecc_pkg.vhd ecc_codec.vhd scrub_bram.vhd scrub_fsm.vhd tb_layer2.vhd 2>/dev/null && \
  ghdl -r --std=08 tb_layer2 --stop-time=50us | tail -4 )
echo ">> archivos Layer 2:"
ls -l "$DEST"/scrub_*.vhd "$DEST"/tb_layer2.vhd "$DEST"/scrub_oracle.py "$DEST"/gen_layer2_vectors.py
